const request = $input.first().json;
const body = request.body;
const payload = body !== null && typeof body === 'object' && !Array.isArray(body)
  ? body
  : {};

const errors = [];
const normalized = {};
const hasOwn = (field) => Object.prototype.hasOwnProperty.call(payload, field);

function validateEmail() {
  const field = 'requester_email';

  if (!hasOwn(field) || payload[field] === null) {
    errors.push({ field, message: `${field} is required` });
    return;
  }

  const value = payload[field];

  if (typeof value !== 'string') {
    errors.push({ field, message: `${field} must be a string` });
    return;
  }

  if (value.length === 0) {
    errors.push({ field, message: `${field} must not be empty` });
    return;
  }

  if (value.length > 254) {
    errors.push({ field, message: `${field} must contain at most 254 characters` });
  }

  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(value)) {
    errors.push({ field, message: `${field} must be a valid email address` });
  }

  if (!errors.some((error) => error.field === field)) {
    normalized[field] = value;
  }
}

function validateTrimmedText(field, minimum, maximum) {
  if (!hasOwn(field) || payload[field] === null) {
    errors.push({ field, message: `${field} is required` });
    return;
  }

  const value = payload[field];

  if (typeof value !== 'string') {
    errors.push({ field, message: `${field} must be a string` });
    return;
  }

  const trimmedValue = value.trim();

  if (trimmedValue.length < minimum || trimmedValue.length > maximum) {
    errors.push({
      field,
      message: `${field} must contain between ${minimum} and ${maximum} characters`,
    });
    return;
  }

  normalized[field] = trimmedValue;
}

validateEmail();
validateTrimmedText('requester_area', 2, 80);
validateTrimmedText('title', 5, 150);
validateTrimmedText('description', 10, 5000);

const isValid = errors.length === 0;

return [{
  json: {
    statusCode: isValid ? 200 : 400,
    response: isValid
      ? { success: true, received: normalized }
      : { success: false, errors },
  },
}];

const expectedRequired = ['category', 'priority', 'summary', 'confidence', 'review_required', 'review_reason'];
const expectedCategories = ['access', 'hardware', 'software', 'network', 'service_request', 'other'];
const expectedPriorities = ['low', 'medium', 'high', 'critical'];
const isPlainObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const sameMembers = (actual, expected) => Array.isArray(actual) && actual.length === expected.length && expected.every((value) => actual.includes(value));
const versions = $('Production Contract Versions and Paths').first().json;
const promptItem = $('Extract Production Prompt Text').first().json;
const schemaItem = $('Extract Production Schema Text').first().json;
const ticket = $('Insert Ticket').first().json;
const pending = $('Insert Prediction Pending').first().json;
const normalized = $('Validate and Normalize Ticket').first().json.response.received;
const base = { ticket_id: ticket.id, ticket_status: ticket.status, ticket_created_at: ticket.created_at, ticket_updated_at: ticket.updated_at, prediction_id: pending.prediction_id, prediction_created_at: pending.prediction_created_at, prediction_pending_updated_at: pending.prediction_updated_at, provider: pending.provider, model: pending.model, prompt_version: versions.prompt_version, schema_version: versions.schema_version, ticket: normalized };
try {
  if (promptItem.error || schemaItem.error) throw new Error('file load failed');
  const promptContent = promptItem.prompt_content;
  const schemaContent = schemaItem.schema_content;
  if (typeof promptContent !== 'string' || !promptContent.includes(versions.prompt_version)) throw new Error('prompt mismatch');
  if (typeof schemaContent !== 'string' || schemaContent.length === 0) throw new Error('schema unavailable');
  const schema = JSON.parse(schemaContent);
  if (!isPlainObject(schema) || schema.$id !== versions.schema_version || schema.type !== 'object' || schema.additionalProperties !== false) throw new Error('schema root mismatch');
  if (!sameMembers(schema.required, expectedRequired) || !isPlainObject(schema.properties) || !sameMembers(Object.keys(schema.properties), expectedRequired)) throw new Error('fields mismatch');
  if (schema.properties.category.type !== 'string' || !sameMembers(schema.properties.category.enum, expectedCategories)) throw new Error('category mismatch');
  if (schema.properties.priority.type !== 'string' || !sameMembers(schema.properties.priority.enum, expectedPriorities)) throw new Error('priority mismatch');
  if (schema.properties.summary.type !== 'string' || schema.properties.summary.minLength !== 1 || schema.properties.summary.maxLength !== 300) throw new Error('summary mismatch');
  if (schema.properties.confidence.type !== 'number' || schema.properties.confidence.minimum !== 0 || schema.properties.confidence.maximum !== 1) throw new Error('confidence mismatch');
  if (schema.properties.review_required.type !== 'boolean') throw new Error('review flag mismatch');
  if (!sameMembers(schema.properties.review_reason.type, ['string', 'null']) || schema.properties.review_reason.maxLength !== 500) throw new Error('review reason mismatch');
  return [{ json: { ...base, contract_valid: true, prompt_content: promptContent, schema } }];
} catch {
  return [{ json: { ...base, contract_valid: false, error_code: 'AI_CONTRACT_LOAD_ERROR', failure_kind: 'internal', attempt_count: 0 } }];
}

const input = $input.first().json;
const ticketData = ['<untrusted_ticket_data>', 'AREA:', input.ticket.requester_area, '', 'TITLE:', input.ticket.title, '', 'DESCRIPTION:', input.ticket.description, '</untrusted_ticket_data>'].join('\n');
return [{ json: { ticket_id: input.ticket_id, prediction_id: input.prediction_id, provider: input.provider, requested_model: 'gpt-5.6-luna', prompt_version: input.prompt_version, schema_version: input.schema_version, schema: input.schema, started_at_ms: Date.now(), request_body: { model: 'gpt-5.6-luna', instructions: input.prompt_content, input: [{ role: 'user', content: [{ type: 'input_text', text: ticketData }] }], text: { format: { type: 'json_schema', name: input.schema_version, schema: input.schema, strict: true } }, reasoning: { effort: 'none' }, store: false, max_output_tokens: 450 } } }];

const items = $input.all();
if (items.length !== 1) throw new Error('AI_REQUEST_COUNT_INVALID');
const item = items[0].json;
if (!item.request_body || item.request_body.model !== item.requested_model) throw new Error('AI_REQUEST_INVALID');
return [{ json: { ...item, http_request_item_count: 1 } }];

const versions = $('Contract Versions and Paths').first().json;
const promptItem = $('Extract Prompt Text').first().json;
const schemaItem = $('Extract Schema Text').first().json;
const promptContent = promptItem.prompt_content;
const schemaContent = schemaItem.schema_content;
const loadError = promptItem.error || schemaItem.error || null;

const base = {
  prompt_version: versions.prompt_version,
  schema_version: versions.schema_version,
  prompt_path: versions.prompt_path,
  schema_path: versions.schema_path,
  prompt_content: promptContent,
  schema_content: schemaContent,
  load_error: loadError,
};

let wrongIdSchema = '{}';
try {
  const parsed = JSON.parse(schemaContent);
  wrongIdSchema = JSON.stringify({ ...parsed, $id: 'wrong-schema-id' });
} catch {}

return [
  { json: { ...base, case_id: 'C0', expected_valid: true } },
  { json: { ...base, case_id: 'C1_INVALID_JSON', expected_valid: false, schema_content: '{ invalid json' } },
  { json: { ...base, case_id: 'C2_WRONG_ID', expected_valid: false, schema_content: wrongIdSchema } },
];

const expectedRequired = ['category', 'priority', 'summary'];
const expectedCategories = ['access', 'hardware', 'software', 'network', 'service_request', 'other'];
const expectedPriorities = ['low', 'medium', 'high', 'critical'];
const isPlainObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const sameMembers = (actual, expected) => Array.isArray(actual) && actual.length === expected.length && expected.every((value) => actual.includes(value));

return $input.all().map((item) => {
  const input = item.json;
  const checks = {
    prompt_load: false,
    prompt_version: false,
    schema_load: false,
    schema_parse: false,
    schema_version: false,
  };

  try {
    if (input.load_error) throw new Error('file load failed');
    if (typeof input.prompt_content !== 'string' || input.prompt_content.length === 0) throw new Error('prompt unavailable or empty');
    checks.prompt_load = true;
    if (!input.prompt_content.includes(input.prompt_version)) throw new Error('prompt version mismatch');
    checks.prompt_version = true;
    if (typeof input.schema_content !== 'string' || input.schema_content.length === 0) throw new Error('schema unavailable or empty');
    checks.schema_load = true;

    const schema = JSON.parse(input.schema_content);
    checks.schema_parse = true;
    if (!isPlainObject(schema)) throw new Error('schema must be an object');
    if (schema.$id !== input.schema_version) throw new Error('schema version mismatch');
    checks.schema_version = true;
    if (schema.type !== 'object' || schema.additionalProperties !== false) throw new Error('schema root mismatch');
    if (!sameMembers(schema.required, expectedRequired)) throw new Error('schema required mismatch');
    if (!isPlainObject(schema.properties) || !sameMembers(Object.keys(schema.properties), expectedRequired)) throw new Error('schema properties mismatch');
    if (schema.properties.category.type !== 'string' || !sameMembers(schema.properties.category.enum, expectedCategories)) throw new Error('category schema mismatch');
    if (schema.properties.priority.type !== 'string' || !sameMembers(schema.properties.priority.enum, expectedPriorities)) throw new Error('priority schema mismatch');
    if (schema.properties.summary.type !== 'string' || schema.properties.summary.minLength !== 1 || schema.properties.summary.maxLength !== 300) throw new Error('summary schema mismatch');

    return {
      json: {
        case_id: input.case_id,
        expected_valid: input.expected_valid,
        contract_valid: true,
        checks,
        prompt_version: input.prompt_version,
        schema_version: input.schema_version,
        prompt_path: input.prompt_path,
        schema_path: input.schema_path,
        schema,
      },
    };
  } catch {
    return {
      json: {
        case_id: input.case_id,
        expected_valid: input.expected_valid,
        contract_valid: false,
        error_code: 'AI_CONTRACT_LOAD_ERROR',
        checks,
        prompt_version: input.prompt_version,
        schema_version: input.schema_version,
        prompt_path: input.prompt_path,
        schema_path: input.schema_path,
      },
    };
  }
});

const contractResults = $input.all().map((item) => item.json);
const actual = contractResults.find((item) => item.case_id === 'C0');
const corruptCases = contractResults.filter((item) => item.case_id !== 'C0');
const contractFailurePass = corruptCases.length === 2 && corruptCases.every((item) => item.contract_valid === false && item.error_code === 'AI_CONTRACT_LOAD_ERROR');

if (!actual || actual.contract_valid !== true || !contractFailurePass) {
  throw new Error('AI_CONTRACT_LOAD_ERROR');
}

const validSoftware = {
  category: 'software',
  priority: 'high',
  summary: 'La aplicación se cierra al iniciar.',
};
const validAccess = {
  category: 'access',
  priority: 'medium',
  summary: 'El usuario no puede autenticarse.',
};

const cases = [
  { case_id: 'A1', expected_valid: true, ai_response: validSoftware },
  { case_id: 'A2', expected_valid: true, ai_response: validAccess },
  { case_id: 'A3', expected_valid: true, ai_response: JSON.stringify(validSoftware) },
  { case_id: 'R1', expected_valid: false, ai_response: '{ invalid json' },
  { case_id: 'R2', expected_valid: false, ai_response: [validSoftware] },
  { case_id: 'R3', expected_valid: false, ai_response: { priority: 'high', summary: 'Falta categoría.' } },
  { case_id: 'R4', expected_valid: false, ai_response: { category: 'software', summary: 'Falta prioridad.' } },
  { case_id: 'R5', expected_valid: false, ai_response: { category: 'software', priority: 'high' } },
  { case_id: 'R6', expected_valid: false, ai_response: { ...validSoftware, extra: true } },
  { case_id: 'R7', expected_valid: false, ai_response: { ...validSoftware, category: 'unknown' } },
  { case_id: 'R8', expected_valid: false, ai_response: { ...validSoftware, category: 'Software' } },
  { case_id: 'R9', expected_valid: false, ai_response: { ...validSoftware, priority: 'urgent' } },
  { case_id: 'R10', expected_valid: false, ai_response: { ...validSoftware, summary: '' } },
  { case_id: 'R11', expected_valid: false, ai_response: { ...validSoftware, summary: '   ' } },
  { case_id: 'R12', expected_valid: false, ai_response: { ...validSoftware, summary: 'x'.repeat(301) } },
  { case_id: 'R13', expected_valid: false, ai_response: { ...validSoftware, summary: 123 } },
  { case_id: 'R14', expected_valid: false, ai_response: null },
  { case_id: 'R15', expected_valid: false, ai_response: {} },
  { case_id: 'R16', expected_valid: false, ai_response: 'Here is the JSON:\n' + JSON.stringify(validSoftware) },
];

return cases.map((testCase) => ({
  json: {
    ...testCase,
    contract_valid: true,
    contract_failure_pass: true,
    contract_checks: actual.checks,
    prompt_version: actual.prompt_version,
    schema_version: actual.schema_version,
    prompt_path: actual.prompt_path,
    schema_path: actual.schema_path,
    schema: actual.schema,
  },
}));

return $input.all().map((item) => {
  const input = item.json;
  const invalid = () => ({
    json: {
      case_id: input.case_id,
      expected_valid: input.expected_valid,
      valid: false,
      error_code: 'AI_RESPONSE_INVALID',
      contract_failure_pass: input.contract_failure_pass,
      contract_checks: input.contract_checks,
      prompt_version: input.prompt_version,
      schema_version: input.schema_version,
    },
  });

  let candidate = input.ai_response;
  if (typeof candidate === 'string') {
    try {
      candidate = JSON.parse(candidate);
    } catch {
      return invalid();
    }
  }

  if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) return invalid();
  const keys = Object.keys(candidate);
  const expectedKeys = ['category', 'priority', 'summary'];
  if (keys.length !== expectedKeys.length || !expectedKeys.every((key) => keys.includes(key))) return invalid();

  const schema = input.schema;
  if (typeof candidate.category !== 'string' || !schema.properties.category.enum.includes(candidate.category)) return invalid();
  if (typeof candidate.priority !== 'string' || !schema.properties.priority.enum.includes(candidate.priority)) return invalid();
  if (typeof candidate.summary !== 'string') return invalid();
  const summaryLength = candidate.summary.trim().length;
  if (summaryLength < schema.properties.summary.minLength || summaryLength > schema.properties.summary.maxLength) return invalid();

  return {
    json: {
      case_id: input.case_id,
      expected_valid: input.expected_valid,
      valid: true,
      data: candidate,
      contract_failure_pass: input.contract_failure_pass,
      contract_checks: input.contract_checks,
      prompt_version: input.prompt_version,
      schema_version: input.schema_version,
    },
  };
});

const results = $input.all().map((item) => item.json);
const expectedIds = ['A1', 'A2', 'A3', 'R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'R7', 'R8', 'R9', 'R10', 'R11', 'R12', 'R13', 'R14', 'R15', 'R16'];
const matrix = {};

for (const caseId of expectedIds) {
  const result = results.find((item) => item.case_id === caseId);
  const passed = Boolean(result) && result.valid === result.expected_valid && (result.valid === true || result.error_code === 'AI_RESPONSE_INVALID');
  matrix[caseId] = passed ? 'PASS' : 'FAIL';
}

const first = results[0];
const contractChecks = first?.contract_checks || {};
const contractLoad = {
  prompt_load: contractChecks.prompt_load === true ? 'PASS' : 'FAIL',
  prompt_version: contractChecks.prompt_version === true ? 'PASS' : 'FAIL',
  schema_load: contractChecks.schema_load === true ? 'PASS' : 'FAIL',
  schema_parse: contractChecks.schema_parse === true ? 'PASS' : 'FAIL',
  schema_version: contractChecks.schema_version === true ? 'PASS' : 'FAIL',
};
const allPass = expectedIds.every((caseId) => matrix[caseId] === 'PASS') && first?.contract_failure_pass === true && Object.values(contractLoad).every((value) => value === 'PASS');

if (!allPass) throw new Error('AI_VALIDATOR_TEST_FAILURE');

return [{
  json: {
    validator_suite: 'PASS',
    accept_cases: 3,
    reject_cases: 16,
    contract_load: contractLoad,
    contract_failure: {
      invalid_schema_json: 'PASS',
      wrong_schema_id: 'PASS',
      error_code: 'AI_CONTRACT_LOAD_ERROR',
    },
    matrix,
    prompt_version: first.prompt_version,
    schema_version: first.schema_version,
  },
}];

const validItems = $input.all().filter((item) => item.json.case_id === 'C0' && item.json.contract_valid === true);

if (validItems.length !== 1) {
  throw new Error('AI_REQUEST_ITEM_COUNT_ERROR');
}

return validItems;

const items = $input.all();
if (items.length !== 1) throw new Error('AI_PERSISTENCE_INPUT_ERROR');

const decodeInput = (encoded) => {
  if (typeof encoded !== 'string' || encoded.length === 0) throw new Error('AI_TEST_INPUT_UNAVAILABLE');
  return Buffer.from(encoded, 'base64').toString('utf8');
};

const testMode = decodeInput($env.SMARTDESK_AI_PERSISTENCE_MODE_B64);
if (!['success', 'failed'].includes(testMode)) throw new Error('AI_PERSISTENCE_INPUT_ERROR');

const ticket = {
  requester_email: decodeInput($env.SMARTDESK_AI_REQUESTER_EMAIL_B64),
  requester_area: decodeInput($env.SMARTDESK_AI_REQUESTER_AREA_B64),
  title: decodeInput($env.SMARTDESK_AI_TITLE_B64),
  description: decodeInput($env.SMARTDESK_AI_DESCRIPTION_B64),
};
if (Object.values(ticket).some((value) => value.trim().length === 0)) throw new Error('AI_TEST_INPUT_UNAVAILABLE');

const contract = items[0].json;
return [{
  json: {
    test_mode: testMode,
    ticket,
    provider: 'openai',
    model: 'gpt-5.6-luna',
    prompt_version: contract.prompt_version,
    schema_version: contract.schema_version,
    schema: contract.schema,
  },
}];

const items = $input.all();
if (items.length !== 1) throw new Error('AI_PENDING_STATE_INVALID');

const pending = items[0].json;
const context = $('Build Persistence Test Input').first().json;
const pendingFieldsAreNull = pending.category === null && pending.priority === null && pending.summary === null && pending.error_code === null;
const metadataMatches = pending.provider === context.provider
  && pending.model === context.model
  && pending.prompt_version === context.prompt_version
  && pending.schema_version === context.schema_version;
if (pending.test_mode !== 'success' || pending.prediction_status !== 'pending' || pending.ticket_status !== 'processing' || !pendingFieldsAreNull || !metadataMatches) {
  throw new Error('AI_PENDING_STATE_INVALID');
}
if (typeof pending.ticket_id !== 'string' || typeof pending.prediction_id !== 'string') throw new Error('AI_PENDING_STATE_INVALID');

const promptContent = $('Extract Prompt Text').first().json.prompt_content;
if (typeof promptContent !== 'string' || promptContent.length === 0) throw new Error('AI_CONTRACT_LOAD_ERROR');

const ticket = context.ticket;
const ticketData = [
  '<untrusted_ticket_data>',
  'AREA:',
  ticket.requester_area,
  '',
  'TITLE:',
  ticket.title,
  '',
  'DESCRIPTION:',
  ticket.description,
  '</untrusted_ticket_data>',
].join('\n');

return [{
  json: {
    ticket_id: pending.ticket_id,
    prediction_id: pending.prediction_id,
    ticket_status: pending.ticket_status,
    prediction_created_at: pending.prediction_created_at,
    prediction_pending_updated_at: pending.prediction_updated_at,
    provider: context.provider,
    requested_model: context.model,
    prompt_version: context.prompt_version,
    schema_version: context.schema_version,
    schema: context.schema,
    pending_verified_before_openai: true,
    started_at_ms: Date.now(),
    request_body: {
      model: context.model,
      instructions: promptContent,
      input: [{
        role: 'user',
        content: [{ type: 'input_text', text: ticketData }],
      }],
      text: {
        format: {
          type: 'json_schema',
          name: context.schema_version,
          schema: context.schema,
          strict: true,
        },
      },
      reasoning: { effort: 'none' },
      store: false,
      max_output_tokens: 300,
    },
  },
}];

const items = $input.all();
if (items.length !== 1) {
  throw new Error('AI_REQUEST_ITEM_COUNT_ERROR');
}

const item = items[0];
const body = item.json.request_body;
if (!body || body.model !== 'gpt-5.6-luna' || body.store !== false || body.reasoning?.effort !== 'none') {
  throw new Error('AI_REQUEST_CONFIGURATION_ERROR');
}
if (body.text?.format?.type !== 'json_schema' || body.text.format.strict !== true) {
  throw new Error('AI_REQUEST_CONFIGURATION_ERROR');
}
if (body.text.format.schema?.$id !== item.json.schema_version) {
  throw new Error('AI_CONTRACT_LOAD_ERROR');
}
if (Object.prototype.hasOwnProperty.call(body, 'tools') || Object.prototype.hasOwnProperty.call(body, 'stream')) {
  throw new Error('AI_REQUEST_CONFIGURATION_ERROR');
}

return [{
  json: {
    ...item.json,
    http_request_item_count: 1,
  },
}];

const response = $input.first().json;
const request = $('Assert Single OpenAI Request').first().json;
const latencyMs = Date.now() - request.started_at_ms;

if (response.status !== 'completed' || response.error) throw new Error('AI_PROVIDER_FAILURE');

const outputTexts = Array.isArray(response.output)
  ? response.output
      .filter((item) => item?.type === 'message' && Array.isArray(item.content))
      .flatMap((item) => item.content)
      .filter((part) => part?.type === 'output_text' && typeof part.text === 'string')
      .map((part) => part.text)
  : [];
if (outputTexts.length !== 1 || outputTexts[0].length === 0) throw new Error('AI_RESPONSE_INVALID');
try { JSON.parse(outputTexts[0]); } catch { throw new Error('AI_RESPONSE_INVALID'); }

return [{
  json: {
    ticket_id: request.ticket_id,
    prediction_id: request.prediction_id,
    ticket_status: request.ticket_status,
    prediction_created_at: request.prediction_created_at,
    prediction_pending_updated_at: request.prediction_pending_updated_at,
    pending_verified_before_openai: request.pending_verified_before_openai,
    provider: request.provider,
    requested_model: request.requested_model,
    reported_model: response.model ?? null,
    prompt_version: request.prompt_version,
    schema_version: request.schema_version,
    schema: request.schema,
    ai_response: outputTexts[0],
    response_status: response.status,
    structured_output: true,
    input_tokens: response.usage?.input_tokens ?? null,
    cached_input_tokens: response.usage?.input_tokens_details?.cached_tokens ?? null,
    output_tokens: response.usage?.output_tokens ?? null,
    total_tokens: response.usage?.total_tokens ?? null,
    latency_ms: latencyMs,
    http_request_item_count: request.http_request_item_count,
  },
}];

const input = $input.first().json;
const base = {
  ticket_id: input.ticket_id,
  prediction_id: input.prediction_id,
  ticket_status: input.ticket_status,
  prediction_created_at: input.prediction_created_at,
  prediction_pending_updated_at: input.prediction_pending_updated_at,
  pending_verified_before_openai: input.pending_verified_before_openai,
  provider: input.provider,
  requested_model: input.requested_model,
  reported_model: input.reported_model,
  prompt_version: input.prompt_version,
  schema_version: input.schema_version,
  response_status: input.response_status,
  structured_output: input.structured_output,
  input_tokens: input.input_tokens,
  cached_input_tokens: input.cached_input_tokens,
  output_tokens: input.output_tokens,
  total_tokens: input.total_tokens,
  latency_ms: input.latency_ms,
  http_request_item_count: input.http_request_item_count,
};
const invalid = () => ({ json: { ...base, valid: false, error_code: 'AI_RESPONSE_INVALID' } });

let candidate = input.ai_response;
if (typeof candidate === 'string') {
  try { candidate = JSON.parse(candidate); } catch { return [invalid()]; }
}
if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) return [invalid()];
const keys = Object.keys(candidate);
const expectedKeys = ['category', 'priority', 'summary'];
if (keys.length !== expectedKeys.length || !expectedKeys.every((key) => keys.includes(key))) return [invalid()];

const schema = input.schema;
if (typeof candidate.category !== 'string' || !schema.properties.category.enum.includes(candidate.category)) return [invalid()];
if (typeof candidate.priority !== 'string' || !schema.properties.priority.enum.includes(candidate.priority)) return [invalid()];
if (typeof candidate.summary !== 'string') return [invalid()];
const summaryLength = candidate.summary.trim().length;
if (summaryLength < schema.properties.summary.minLength || summaryLength > schema.properties.summary.maxLength) return [invalid()];

