const invalid = () => ({ json: { ...input, ai_response: undefined, valid: false, error_code: 'AI_RESPONSE_INVALID', failure_kind: 'permanent' } });
let candidate;
try { candidate = JSON.parse(input.ai_response); } catch { return [invalid()]; }
if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) return [invalid()];
const expectedKeys = ['category', 'priority', 'summary', 'confidence', 'review_required', 'review_reason'];
const keys = Object.keys(candidate);
if (keys.length !== expectedKeys.length || !expectedKeys.every((key) => keys.includes(key))) return [invalid()];
