return [{ json: { ...input, ai_response: undefined, valid: true, category: candidate.category, priority: candidate.priority, summary: candidate.summary.trim(), confidence: candidate.confidence, review_required: candidate.review_required, review_reason: candidate.review_required ? candidate.review_reason.trim() : null } }];

